import numpy as np, collections, statistics, time
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import Ridge, HuberRegressor, QuantileRegressor
from sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor, HistGradientBoostingRegressor
import research as R

# Precompute datasets once
DIRECT=R.datasets('direct',15.0)
CURRENT=R.datasets('current',0.0)
DELTA=R.datasets('delta',15.0)
EVALIDS=set(id(r) for r in R.DATA if r['eval3a'])

def subset(ds, mode='all'):
    if mode=='all': return ds
    if mode=='3a': return [(r,x,y) for r,x,y in ds if r['eval3a']]
    if mode=='3a2': return [(r,x,y) for r,x,y in ds if r['eval3a'] or (r['i']<=10 and r['i']<=44)]
    return ds

def weights_for(tr):
    c=collections.Counter(r['person'] for r,_,_ in tr)
    w=np.array([1.0/c[r['person']] for r,_,_ in tr])
    return w/w.mean()

def lopo(ds, kind, params=None, weighting=False, train_mode='all', label=''):
    params=params or {}
    trds=subset(ds,train_mode)
    preds=[]; recs=[]; ys=[]
    for p in R.PERSONS:
        tr=[(r,x,y) for r,x,y in trds if r['person']!=p]
        te=[(r,x,y) for r,x,y in ds if r['person']==p]
        if not te: continue
        Xtr=np.array([x for _,x,_ in tr]); ytr=np.array([y for _,_,y in tr])
        Xte=np.array([x for _,x,_ in te])
        w=weights_for(tr) if weighting else None
        if kind=='ridge':
            sc=StandardScaler().fit(Xtr); Xs=sc.transform(Xtr); Xts=sc.transform(Xte)
            model=Ridge(alpha=params['alpha'],fit_intercept=True,solver='cholesky')
            model.fit(Xs,ytr,sample_weight=w); pr=model.predict(Xts)
        elif kind=='huber':
            sc=StandardScaler().fit(Xtr); Xs=sc.transform(Xtr); Xts=sc.transform(Xte)
            model=HuberRegressor(epsilon=params.get('eps',1.35),alpha=params.get('alpha',1.0),max_iter=300)
            model.fit(Xs,ytr,sample_weight=w); pr=model.predict(Xts)
        elif kind=='quantile':
            sc=StandardScaler().fit(Xtr); Xs=sc.transform(Xtr); Xts=sc.transform(Xte)
            model=QuantileRegressor(quantile=.5,alpha=params['alpha'],solver='highs')
            model.fit(Xs,ytr,sample_weight=w); pr=model.predict(Xts)
        else:
            if kind=='rf': model=RandomForestRegressor(n_estimators=params.get('n',120),max_depth=params.get('depth',10),min_samples_leaf=params.get('leaf',5),random_state=1,n_jobs=1)
            elif kind=='et': model=ExtraTreesRegressor(n_estimators=params.get('n',120),max_depth=params.get('depth',12),min_samples_leaf=params.get('leaf',5),random_state=1,n_jobs=1)
            elif kind=='gb': model=GradientBoostingRegressor(random_state=1,n_estimators=params.get('n',120),max_depth=params.get('depth',2),learning_rate=params.get('lr',.05),subsample=.9,loss=params.get('loss','absolute_error'))
            elif kind=='hgb': model=HistGradientBoostingRegressor(random_state=1,max_iter=params.get('n',120),max_depth=params.get('depth',3),learning_rate=params.get('lr',.05),l2_regularization=params.get('l2',1),loss='absolute_error')
            if w is None: model.fit(Xtr,ytr)
            else: model.fit(Xtr,ytr,sample_weight=w)
            pr=model.predict(Xte)
        preds.extend(pr); recs.extend([r for r,_,_ in te]); ys.extend([y for _,_,y in te])
    return summarize(recs,ys,preds,label)

def summarize(recs,ys,preds,label):
    errs=collections.defaultdict(list); biases=collections.defaultdict(list)
    for r,y,yp in zip(recs,ys,preds):
        if id(r) not in EVALIDS: continue
        errs[r['person']].append(abs(yp-y)); biases[r['person']].append(yp-y)
    vals=[statistics.mean(v) for v in errs.values()]
    allerr=[e for v in errs.values() for e in v]
    res=np.array([yp-y for yp,y in zip(preds,ys)])
    q=[round(float(np.quantile(res,x)),3) for x in [.05,.1,.5,.9,.95]]
    print(label,'pbMAE',round(statistics.mean(vals),4),'MAE',round(statistics.mean(allerr),4),'bias',round(float(np.mean(res)),3),'q',q,'per',{p:round(statistics.mean(v),2) for p,v in sorted(errs.items())})
    return statistics.mean(vals),list(zip(recs,ys,preds))

def combo(cur_model,del_model,label='combo'):
    # cur_model/del_model are outputs (score, results with (rec,y,yp)); add per rec predictions
    cm={id(r):yp for r,y,yp in cur_model[1]}; dm={id(r):yp for r,y,yp in del_model[1]}
    recs=[];ys=[];preds=[]
    for r,y,_ in cur_model[1]:
        if id(r) in dm:
            recs.append(r); ys.append(y+dm[id(r)]); preds.append(cm[id(r)]+dm[id(r)])
    # Need true future y for evaluation; use rec['fut'] from DATA
    ys=[r['fut'] for r in recs]
    return summarize(recs,ys,preds,label)

if __name__=='__main__':
    print('sizes',len(DIRECT),len(CURRENT),len(DELTA))
    R.baseline_eval()
    t=time.time()
    for weighting in [False,True]:
        for tm in ['all','3a']:
            for a in [0.3,1,3,10,30,100,300]:
                lopo(DIRECT,'ridge',{'alpha':a},weighting,tm,f'Ridge a={a} w={weighting} tr={tm}')
    print('elapsed',time.time()-t)
